void LoadEnemies()
{
    string json = Resources.Load<TextAsset>("enemies").text;
    EnemyDatabase db = JsonUtility.FromJson<EnemyDatabase>(json);

    enemyCache = new Dictionary<string, EnemyData>();
    foreach (var enemy in db.enemies)
    {
        enemyCache[enemy.id] = enemy;
    }
}

EnemyData GetEnemy(string id)
{
    return enemyCache[id]; // acceso O(1)
}

